-- بند الأثاث غير الطبي + إدراجه في نطاقي المدخل الرئيسي والتأهيل العام
insert into public.ls_items (code, grp, title, descr, sort) values
('LS-34', 'الأعمال المعمارية والتشطيبات', 'الأثاث غير الطبي', 'توريد وتركيب الأثاث غير الطبي في النطاق (مقاعد الانتظار، مكاتب وكراسي، طاولات، خزائن ووحدات تخزين متنقلة، ستائر ومفروشات، سلال ولوازم) حسب جداول الأثاث والمخططات والمواصفات المعتمدة، شاملاً التجميع والتثبيت والتوزيع في مواقعه وإزالة التغليف، مع عينات واعتماد الألوان والخامات قبل التوريد.', 165)
on conflict (code) do nothing;
update public.ls_templates set codes = array_append(codes, 'LS-34'), updated_at = now() where name in ('تطوير مدخل رئيسي', 'تأهيل عام (قسم / جناح)') and not ('LS-34' = any(codes));
